  "snapshot.notice": "சேமிக்கப்பட்ட சந்தைத் தரவு காட்டப்படுகிறது. நேரடி புதுப்பிப்புகள் இடைநிறுத்தப்பட்டுள்ளதால் மிகப் புதிய விளம்பரங்களும் விலை மாற்றங்களும் இல்லாமல் இருக்கலாம்.",
  "snapshot.noticeAgo": "{ago}{abs} இலிருந்து சேமிக்கப்பட்ட சந்தைத் தரவு காட்டப்படுகிறது. நேரடி புதுப்பிப்புகள் இடைநிறுத்தப்பட்டுள்ளதால் மிகப் புதிய விளம்பரங்களும் விலை மாற்றங்களும் இல்லாமல் இருக்கலாம்.",
  "transfer.agreement": "விற்பனை ஒப்பந்தம் (PDF)",
  "transfer.agreementBody": "உங்களுக்குத் தெரிந்ததை நிரப்புங்கள். வெற்றுப் புலங்கள் கையால் நிரப்பக் கோடுகளாக அச்சிடப்படும். நீங்கள் தட்டச்சு செய்வது எதுவும் உங்கள் சாதனத்தை விட்டு வெளியேறாது.",
  "transfer.checklist": "பரிமாற்றச் சரிபார்ப்புப் பட்டியல்",
  "transfer.class": "வாகன வகை",
  "transfer.cost": "பரிமாற்றச் செலவு மதிப்பீடு",
  "transfer.costNote": "தோராயமானது மட்டுமே. தற்போதைய கட்டணங்களை DMT இடம் சரிபார்க்கவும். தாமதப் பரிமாற்ற அபராதங்கள் சேர்க்கப்படவில்லை.",
  "transfer.deadline": "உங்கள் பரிமாற்றக் காலக்கெடு",
  "transfer.description": "படிப்படியான சரிபார்ப்புப் பட்டியல், உங்கள் 14 நாள் காலக்கெடு, செலவு மதிப்பீடு மற்றும் அச்சிடக்கூடிய விற்பனை ஒப்பந்தம். இலங்கையில் பயன்படுத்திய வாகனங்களை வாங்குபவர்களுக்கும் விற்பவர்களுக்கும்.",
  "transfer.download": "விற்பனை ஒப்பந்தத்தைப் பதிவிறக்கு",
  "transfer.extras": "பிற செலவுகள்: DMT பதிவு, வழக்கறிஞர், ஆய்வு (LKR)",
  "transfer.extrasLine": "பிற",
  "transfer.eyebrow": "பாதுகாப்பான பரிமாற்றக் கருவி",
  "transfer.fee": "DMT பரிமாற்றக் கட்டணம் (தோராயம்)",
  "transfer.generating": "PDF தயாராகிறது…",
  "transfer.legal": "இது பொதுவான மாதிரி, சட்ட ஆலோசனை அல்ல. கடனில் வாங்கிய அல்லது அதிக மதிப்புள்ள வாகனங்களுக்கு, வழக்கறிஞரிடம் சரிபார்க்கச் சொல்லுங்கள்.",
  "transfer.pdfError": "PDF ஐ உருவாக்க முடியவில்லை. மீண்டும் முயற்சிக்கவும்.",
  "transfer.pdfReady": "விற்பனை ஒப்பந்தம் பதிவிறக்கப்பட்டது",
  "transfer.price": "விற்பனை விலை (LKR)",
  "transfer.progress": "{total} இல் {done} முடிந்தது",
  "transfer.saleDate": "விற்பனை தேதி",
  "transfer.stamp": "விற்பனை மதிப்பின் மீதான முத்திரை வரி, விதிக்கப்பட்டால் (%)",
  "transfer.stampLine": "முத்திரை வரி",
  "transfer.strictNo": "14 நாள் விதி ஏற்கனவே பொருந்தும். கடுமையான அமலாக்கம் {date} முதல் தொடங்கும்.",
  "transfer.strictNotice": "2026 டிசம்பர் 1 முதல், விற்பனையிலிருந்து 14 நாட்களுக்குள் உரிமை மாற்றங்கள் சமர்ப்பிக்கப்பட வேண்டும் என்ற விதியைக் கடுமையாக அமல்படுத்துவதாக மோட்டார் போக்குவரத்துத் திணைக்களம் கூறுகிறது. பரிமாற்றம் பதிவு செய்யப்படும் வரை வாகனத்திற்கு விற்பனையாளர் பொறுப்பாக்கப்படலாம். விதிகளும் கட்டணங்களும் மாறலாம், எனவே இங்குள்ள எந்த எண்ணையும் நம்புவதற்கு முன் DMT இடம் சரிபார்க்கவும்.",
  "transfer.strictYes": "இது கடுமையான அமலாக்கத்தின் கீழ் வருகிறது ({date} முதல்).",
  "transfer.submitBy": "DMT க்குப் பரிமாற்றத்தைச் சமர்ப்பிக்க வேண்டிய நாள்",
  "transfer.title": "உரிமையைப் பாதுகாப்பாக மாற்றுங்கள்",
  "transfer.total": "மொத்தம்",
  "trust.crossSiteUnavailable": "இப்போது தள-இடை வரலாற்றை ஏற்ற முடியவில்லை, எனவே நகல் விளம்பர மற்றும் odometer சோதனைகள் தவிர்க்கப்பட்டன. பின்னர் மீண்டும் முயற்சிக்கவும்.",
  "trust.customs": "சுங்க வாகனச் சோதனை",
  "trust.customsBody": "இறக்குமதி செய்யப்பட்ட வாகனம் சட்டப்படி விடுவிக்கப்பட்டதை உறுதிப்படுத்தும் (chassis எண் + OTP; தனிப்பட்ட பயன்பாடு).",
